mapper.update:
/* saleson.shop.kakaolink.KakaoLinkMapper.updateLoginSession 로그인 사용자 로그아웃 처리 */
UPDATE OP_USER_LOGIN
	SET SESSION_ID = 'KAKAO_LINK_CLEAR'
WHERE 1=1
	AND USER_ID = 
				#{value}

/* saleson.shop.kakaolink.KakaoLinkMapper.kakaoLinkClear 카카오 아이디 삭제 */
		UPDATE OP_USER
			SET KAKAO_USER_KEY = NULL
		WHERE 1=1
			AND USER_ID = #{value}

/* saleson.shop.kakaolink.KakaoLinkMapper.kakaoLinkClearByKakaoUserKey 카카오 아이디 삭제 */
		UPDATE OP_USER
			SET KAKAO_USER_KEY = NULL
		WHERE 1=1
			AND KAKAO_USER_KEY = #{value}

mapper.insert:
/* saleson.shop.kakaolink.KakaoLinkMapper.insertNaverAuthLoginInfo 네이버 인증 정보 추가 */
	INSERT INTO G_NAVER_AUTH_LOGIN_INFO_MNG
		(
			AUTH_TEMP_ID
			, ACCESS_TOKEN
		)
	VALUES
		(
			#{txId}
			, #{accessToken}
		)

mapper.delete:
/* saleson.shop.kakaolink.KakaoLinkMapper.deleteNaverAuthLoginInfoByAccessToken 네이버 인증 정보 삭제 */
		DELETE G_NAVER_AUTH_LOGIN_INFO_MNG
		WHERE 1=1
			AND ACCESS_TOKEN = #{value}

/* saleson.shop.kakaolink.KakaoLinkMapper.deleteNaverAuthLoginInfoByTxId 네이버 인증 정보 삭제 */
		DELETE G_NAVER_AUTH_LOGIN_INFO_MNG
		WHERE 1=1
			AND AUTH_TEMP_ID = #{value}
